mapper.select:
SELECT f.* FROM `t_archive_file` f WHERE f.`del_flag` = 0 AND f.`archive_id` IN
#{id}
ORDER BY f.`archive_id`, f.`sort_no`, f.`seq_no`

SELECT COUNT(1) AS fileCount, COALESCE(SUM(f.`file_size`), 0) AS totalSize
FROM `t_archive_file` f
WHERE f.`del_flag` = 0 AND f.`archive_id` = #{archiveId}
